   if(File.Exists(Scene))throw new InvalidOperationException("Preserve the authored toy stadium; use explicit targeted upgrades.");var m=SportsEventAuthoring.Begin<HaulerMatch>(Folder);m.setup.count=4;m.option=1;m.NormalizeSetup();m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();
