   var floor=GameObject.CreatePrimitive(PrimitiveType.Cylinder);floor.name="Continuous round toy collection arena";floor.transform.position=new Vector3(0,-1,0);floor.transform.localScale=new Vector3(180,1,180);UnityEngine.Object.DestroyImmediate(floor.GetComponent<Collider>());floor.GetComponent<Renderer>().sharedMaterial=dark;var floorShape=floor.AddComponent<MeshCollider>();floorShape.sharedMesh=floor.GetComponent<MeshFilter>().sharedMesh;floorShape.sharedMaterial=physics;SportsDrivingSurfaceAuthoring.MarkHierarchy(floor.transform);
   var grass=SportsEventAuthoring.Mat(Folder,"Vista carnival meadow",new Color(.36f,.57f,.23f),.05f);grass.mainTexture=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer").diffuseTexture;grass.mainTextureScale=Vector2.one*40;var ground=SportsEventAuthoring.Box("Finished carnival surrounding landscape",new Vector3(0,-2,0),new Vector3(600,1,600),grass,physics);SportsDrivingSurfaceAuthoring.MarkHierarchy(ground.transform);
   var palette=new Material[8];for(int i=0;i<8;i++)palette[i]=SportsEventAuthoring.Mat(Folder,"Shared candy ball palette "+i,Color.HSVToRGB(i/8f,.78f,.95f),.5f);var gold=SportsEventAuthoring.Mat(Folder,"Distinct golden bonus rubber",new Color(1,.67f,.025f),.55f);gold.SetFloat("_Metallic",.6f);var bomb=SportsEventAuthoring.Mat(Folder,"Readable charcoal fuse ball",new Color(.025f,.02f,.035f),.4f);var fuse=SportsEventAuthoring.Mat(Folder,"Warm bomb fuse spark",new Color(1,.28f,.02f),.2f);fuse.EnableKeyword("_EMISSION");fuse.SetColor("_EmissionColor",new Color(1,.15f,.01f)*2);
