    int row=i/16,col=i%16;bool special=i%23==0,hazard=!special&&i%37==0;float radius=special?1.1f:hazard?1:.9f;var root=new GameObject(hazard?"Readable fuse bomb ball "+i:special?"Rare golden five-point ball "+i:"Physical colored toy ball "+i);root.transform.SetParent(m.ballGroup);root.transform.position=new Vector3((col-7.5f)*4,3+(i%5)*1.3f,(row-7.5f)*4);
    var shell=GameObject.CreatePrimitive(PrimitiveType.Sphere);shell.name="Authored rubber ball shell";shell.transform.SetParent(root.transform,false);shell.transform.localScale=Vector3.one*radius*2;UnityEngine.Object.DestroyImmediate(shell.GetComponent<Collider>());shell.GetComponent<Renderer>().sharedMaterial=hazard?bomb:special?gold:palette[i%8];
    var shape=root.AddComponent<SphereCollider>();shape.radius=radius;shape.sharedMaterial=contact;var body=root.AddComponent<Rigidbody>();body.mass=3;body.linearDamping=.02f;body.angularDamping=.08f;body.maxLinearVelocity=32;body.maxAngularVelocity=16;body.sleepThreshold=.08f;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.isKinematic=true;
    var actor=root.AddComponent<HaulerBall>();actor.id=i;actor.value=hazard?0:special?5:1;actor.body=body;actor.shape=shape;m.balls[i]=actor;
    if(hazard){var wire=root.AddComponent<LineRenderer>();wire.useWorldSpace=false;wire.positionCount=8;wire.widthMultiplier=.12f;wire.sharedMaterial=fuse;for(int k=0;k<8;k++)wire.SetPosition(k,new Vector3(Mathf.Sin(k*.25f)*.3f,radius+k*.11f,0));var spark=GameObject.CreatePrimitive(PrimitiveType.Sphere);spark.name="Obvious burning fuse";spark.transform.SetParent(root.transform,false);spark.transform.localPosition=wire.GetPosition(7);spark.transform.localScale=Vector3.one*.35f;spark.GetComponent<Renderer>().sharedMaterial=fuse;UnityEngine.Object.DestroyImmediate(spark.GetComponent<Collider>());}
   }
