   }
   var venue=new GameObject("Finished toy carnival terraces and giant cargo display").transform;Bleachers(venue,steel);var cargo=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckTrailerPlug/Prefabs/Cargo Trailer Render Model.prefab");foreach(int side in new[]{-1,1}){var display=SportsReplayVisuals.Copy(cargo.transform);display.name="Existing enormous cargo trailer carnival display";display.transform.SetParent(venue,true);display.transform.position=new Vector3(side*104,4,75);display.transform.rotation=Quaternion.Euler(0,90,0);display.transform.localScale*=1.8f;}
   var panel=SportsEventAuthoring.Box("Giant toy carnival actual score display",new Vector3(0,16,91),new Vector3(90,15,1.2f),dark);var label=new GameObject("Original toy scoreboard readable typography").AddComponent<TextMeshPro>();label.font=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme").headingFont;label.transform.position=new Vector3(0,16,90.3f);label.rectTransform.sizeDelta=new Vector2(86,13);label.enableAutoSizing=true;label.fontSize=24;label.fontSizeMax=28;label.fontSizeMin=14;label.color=new Color(1,.94f,.7f);label.alignment=TextAlignmentOptions.Center;var scoreboard=panel.AddComponent<HaulerBoard>();scoreboard.match=m;scoreboard.label=label;
   m.broadcast=SportsEventAuthoring.Camera("Whole toy collection arena broadcast");m.broadcast.view.farClipPlane=2400;m.broadcast.view.orthographic=true;m.framing=m.broadcast.gameObject.AddComponent<SportsCameraFit>();m.framing.cameraTarget=m.broadcast.view;m.framing.arenaFit=true;m.framing.topInset=.1f;m.framing.bottomInset=.2f;m.cameras=new[]{m.broadcast.view};SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);m.drivingViews=SportsDrivingViewsAuthoring.Install(m,m.trucks,m.broadcast,Folder);m.drivingViews.independentViewModes=true;m.atmosphere=SportsChaosAuthoring.Weather(m,Folder);m.atmosphere.presets=SportsWeatherPresetsAuthoring.EnsureCatalog();m.drivingViews.rally.weather=m.atmosphere;SportsWeatherPickerAuthoring.Install(m,m.atmosphere.presets,new Vector2(350,-180));var hud=m.gameObject.AddComponent<SportsExpansionViewHud>();hud.match=m;hud.views=m.drivingViews;SportsUIAuthoring.Button(m.menus.pages[6].transform,"WATCH THE BALL HEIST","watchhauler",new Vector2(0,-245),new Vector2(520,48));Artwork(m);SportsBroadcastAuthoring.ApplyScene();SportsScenicGradeAuthoring.Install(m.gameObject,new[]{m.broadcast.view}.Concat(m.drivingViews.rally.views.Select(v=>v.view)).ToArray(),Folder,-.35f);SportsMatchAudioAuthoring.Install(m,m.trucks);SportsEventAuthoring.Save(Folder);
