  public static void UpgradeIntake()
  {
   EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<HaulerMatch>();foreach(var scoop in m.scoops){scoop.mouth.center=new Vector3(0,1.65f,4.5f);scoop.mouth.size=new Vector3(6.5f,2.8f,4);EditorUtility.SetDirty(scoop.mouth);}SportsMatchAudioAuthoring.Install(m,m.trucks);EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();Debug.Log("HAULER_INTAKE_LIP_ALIGNED actual sphere overlap at physical teeth, no distant pickup scan");
  }
  static HaulerScoop Scoop(HaulerMatch m,int slot,SportsEventTruck t,Material steel,Material paint,PhysicsMaterial physics)
  {
   var root=new GameObject("Actual animated telescoping collection scoop").transform;root.SetParent(t.transform,false);root.localPosition=new Vector3(0,.35f,4.5f);var scoop=root.gameObject.AddComponent<HaulerScoop>();scoop.match=m;scoop.slot=slot;scoop.moving=root;var renderers=new List<Renderer>();
   for(int slice=0;slice<8;slice++){float z=(slice+.5f)*.75f,y=.25f+.6f*Mathf.Pow(1-z/6,2);var basePlate=SportsEventAuthoring.Box("Modeled curved scoop floor segment",new Vector3(0,y,z),new Vector3(7.2f,.18f,.77f),steel,physics,root);basePlate.transform.localRotation=Quaternion.Euler(Mathf.Atan(.2f*(1-z/6))*Mathf.Rad2Deg,0,0);}
   foreach(int side in new[]{-1,1}){var rail=SportsEventAuthoring.Box("Colored scoop side wall",new Vector3(side*3.6f,1.5f,3),new Vector3(.3f,2.6f,6),paint,physics,root);renderers.Add(rail.GetComponent<Renderer>());for(int stripe=0;stripe<5;stripe++)SportsEventAuthoring.Box("Reinforced scoop side rivet",new Vector3(side*3.77f,1.5f,stripe*1.15f+.7f),new Vector3(.12f,.18f,.18f),steel,null,root);}
   renderers.Add(SportsEventAuthoring.Box("Curved scoop reinforced rear wall",new Vector3(0,1.5f,.1f),new Vector3(7.2f,2.6f,.25f),paint,physics,root).GetComponent<Renderer>());
   for(int tooth=0;tooth<12;tooth++){var plate=SportsEventAuthoring.Box("Actual leading scoop tooth",new Vector3((tooth-5.5f)*.6f,.22f,6.1f),new Vector3(.35f,.18f,.65f),steel,physics,root);plate.transform.localRotation=Quaternion.Euler(8,0,0);}
   var mouth=new GameObject("Genuine physical scoop mouth trigger");mouth.transform.SetParent(root,false);var volume=mouth.AddComponent<BoxCollider>();volume.center=new Vector3(0,1.65f,4.5f);volume.size=new Vector3(6.5f,2.8f,4);volume.isTrigger=true;scoop.mouth=volume;mouth.AddComponent<HaulerMouth>().scoop=scoop;scoop.paint=renderers.ToArray();scoop.Deploy(false,true);return scoop;
  }
  static void CargoHopper(Transform truck,Material steel,Material paint,PhysicsMaterial physics)
  {
   var root=new GameObject("Visible open rear tractor cargo hopper").transform;root.SetParent(truck,false);root.localPosition=new Vector3(0,2.2f,-3.7f);SportsEventAuthoring.Box("Modeled cargo hopper base",Vector3.zero,new Vector3(4.8f,.22f,6.6f),steel,physics,root);foreach(int side in new[]{-1,1}){SportsEventAuthoring.Box("Open hopper raised side rail",new Vector3(side*2.4f,1,0),new Vector3(.16f,2,6.6f),paint,physics,root);SportsEventAuthoring.Box("Open hopper raised end rail",new Vector3(0,1,side*3.3f),new Vector3(4.8f,2,.16f),steel,physics,root);}
  }
  static void Bleachers(Transform root,Material steel)
  {
   var destination=SceneManager.GetActiveScene();var source=EditorSceneManager.OpenScene(LWS.TruckHotPotato.Editor.HotPotatoAuthoring.Scene,OpenSceneMode.Additive);
   try
   {
    SceneManager.SetActiveScene(destination);var crowd=source.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<LWS.TruckHotPotato.HotPotatoMatch>(true)).First().crowd;
    for(int side=-1;side<=1;side+=2)for(int row=0;row<4;row++)
    {
     SportsEventAuthoring.Box("Protected toy carnival tiered steel bleacher",new Vector3(side*(104+row*2),1+row,0),new Vector3(2.5f,1.5f,90),steel,null,root);
     for(int i=0;i<36;i++){var batch=crowd.batches[(i+row)%crowd.batches.Length];var fan=new GameObject("Reused posed toy carnival spectator");fan.transform.SetParent(root);fan.transform.SetPositionAndRotation(new Vector3(side*(104+row*2),1.75f+row,-43+i*2.4f),Quaternion.Euler(0,side<0?90:-90,0));fan.AddComponent<MeshFilter>().sharedMesh=batch.idle;fan.AddComponent<MeshRenderer>().sharedMaterials=batch.materials;}
    }
   }finally{EditorSceneManager.CloseScene(source,true);SceneManager.SetActiveScene(destination);}
  }
  static void Artwork(HaulerMatch m)
  {
   var logo=SportsRetroMenuAuthoring.LoadLogo(Folder);foreach(int index in new[]{0,4}){var page=m.menus.pages[index];var art=SportsUIAuthoring.Rect("Original sport title artwork",page.transform,new Vector2(260,160),new Vector2(-560,365)).AddComponent<UnityEngine.UI.Image>();art.sprite=logo;art.preserveAspect=true;art.raycastTarget=false;var title=page.transform.Find("Title").GetComponent<TMP_Text>();title.rectTransform.anchoredPosition+=Vector2.right*140;title.rectTransform.sizeDelta=new Vector2(1000,title.rectTransform.sizeDelta.y);}
   var material=SportsEventAuthoring.Mat(Folder,"Original grungy toy collection signage",Color.white);material.shader=Shader.Find("Universal Render Pipeline/Unlit");material.mainTexture=logo.texture;material.SetFloat("_Surface",1);material.SetFloat("_SrcBlend",5);material.SetFloat("_DstBlend",10);material.SetFloat("_ZWrite",0);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.renderQueue=3000;
   foreach(int side in new[]{-1,1}){var sign=GameObject.CreatePrimitive(PrimitiveType.Quad);sign.name="Original toy carnival venue artwork";UnityEngine.Object.DestroyImmediate(sign.GetComponent<Collider>());sign.transform.position=new Vector3(side*63,16,94);sign.transform.localScale=new Vector3(35,19,1);sign.GetComponent<Renderer>().sharedMaterial=material;}
  }
